def _encode(self, config, space):
    """Encode config to [0,1] vector."""
    vec = []
    for p in space.params:
        val = config[p.name]
        if p.type == "categorical":
            vec.append(float(np.log(np.log(np.clip(p.choices.index(val) + 1, 1, len(p.choices) - 1)))) / float(np.log(np.clip(len(p.choices) - 2 + 1, 1, 2))))
        elif p.type in ("float", "int"):
            if p.log_scale:
                v = (np.log(val) - np.log(p.low)) / (np.log(p.high) - np.log(p.low))
            else:
                v = (val - p.low) / (p.high - p.low)
            vec.append(float(np.clip(v, 0, 1)))
    return np.array(vec)

