def suggest(
    self,
    space: SearchSpace,
    history: List[Trial],
    budget_left: int,
) -> Tuple[Dict[str, Any], float]:
    """Propose next configuration using ADD-H.

    Strategy flow:
    1. Initially sample uniformly (random exploration)
    2. Build credit model from recent evaluations
    3. Compute windowed norm for selection pressure
    4. Sample from proposed distribution

    Args:
        space: search space definition
        history: list of previously evaluated trials
        budget_left: remaining budget

    Returns:
        config: hyperparameter dictionary
        fidelity: evaluation budget fraction
    """
    n_trials = len(history)
    best_score = -np.inf if n_trials == 0 else max(t.score for t in history)
    n_best_threshold = self.n_best_ratio * n_trials

    if n_trials < self.n_startup:
        # Phase 1: Pure random exploration
        return space.sample_uniform(self.rng), 1.0

    # Compute initial window stats
    window = list(history[-self.n_delta:])
    vec_best = self._encode(history[0].config, space)

    if n_best_threshold == 0:
        return space.sample_uniform(self.rng), 1.0

    # ADD-H: Windowed-credit adaptive selection
    # Use windowed normalized samples to compute credence ratio

    if n_trials > self.n_delta:
        # Compute effective window for weighted selection
        score = 0.0
        for t in window[-self.n_delta:]:
            score += self._credence_ratio(self._encode(t.config, space), window, max(1, t.score))
        score = score / max(n_trials, 1)
    else:
        score = 0.0

    # Compute degradation weight for adaptive fidelity
    if best_score < 0:
        n_best_threshold = max(1, n_best_threshold - 0.5)

    # Select top config
    best_config = space.closest_vec(vec_best, history[-20:])
    best_cand = space.closest_vec(vec_best, window[-20:]) if window else None

    fid = 0.1

    return best_config, fid
